syntax = "proto3";
package game;

// 心跳请求。
// time: 客户端当前毫秒时间戳，服务端原样返回，用于前端计算延迟。
message HeartBeatReq {
    uint64 time = 1; // 客户端发送的毫秒时间戳
}

// 心跳响应。
// time: 服务端回包时返回请求中的 time。
message HeartBeatRes {
    uint64 time = 1; // 原样返回的毫秒时间戳
}

// 空请求结构，保留给无参数接口使用。
message EmptyReq {
}

// 单个下注区域信息。
// 典型格式:
// {
//   "icon": 3,
//   "money": 10000
// }
message BetArea {
    uint32 icon = 1;  // 宝箱区域ID，范围 1~8
    uint64 money = 2; // 在该宝箱区域累计下注金额
}

// 单个中奖区域结果信息。
// 典型格式:
// {
//   "icon": 5,
//   "ratio": 8,
//   "winMoney": 80000
// }
message ResultArea {
    uint32 icon = 1;     // 中奖宝箱区域ID，范围 1~8
    uint32 ratio = 2;    // 该区域赔率
    uint64 winMoney = 3; // 玩家在该区域实际赢得的金币
}

// 排行榜玩家信息。
// 用于结算前三展示、当日排行等列表。
message RankInfo {
    uint64 uid = 1;    // 玩家ID
    string name = 2;   // 玩家昵称
    string head = 3;   // 玩家头像URL
    uint64 score = 4;  // 排行分数，当前实现通常为净赢金币
    uint32 rank = 5;   // 排名，从 1 开始
}

message RoundRecord {
    uint64 ctime = 1;          // 结算时间戳(秒)
    uint32 round = 2;          // 局号
    repeated BetArea betAreas = 3;      // 本 局下注明细列表
    repeated ResultArea resultAreas = 4; // 本局开奖区域返奖明细, 如果玩家没中奖, 也要展示开奖的区域, winMoney=0
    uint32 resultType = 5;     // 开奖类型：1 普通开奖，2 大奖开奖  2的时候前端需要多展示一个大奖图标
}

// 宝箱基础配置。
// 用于前端渲染宝箱区域和赔率。
message BoxConfig {
    uint32 icon = 1;   // 宝箱区域ID，范围 1~8
    string name = 2;   // 宝箱显示名或配置名
    uint32 ratio = 3;  // 宝箱赔率
}

// 单次下注请求。
// 每次点击一个宝箱区域发送一次，不负责自动续投。
message BetReq {
    uint32 iconId = 1;   // 本次下注的宝箱区域ID，范  围 1~8
    uint64 money = 2;    // 本次下注金额，必须是合法筹码档位之一
    uint32 roomId = 3;   // 房间ID，透传平台扣费接口
    string ticket = 4;   // 玩家票据，透传平台扣费接口
    uint32 gameType = 5; // 游戏类型，透传平台接口
}

// 单次下注响应。
// 返回当前这一次下注后的个人下注汇总与最新余额。
message BetRes {
    uint32 code = 1;      // 返回码，0 成功，非 0 失败
    string desc = 2;      // 返回描述
    int32 tipType = 3;    // 提示类型，前端可据此决定弹窗样式
    uint64 userMoney = 4; // 扣费后的玩家最新余额
    repeated BetArea betTotal = 5; // 当前局玩家全部下注汇总
    uint32 iconId = 6;   // 本次下注的宝箱区域ID，范围 1~8
}

// 广播其它用户下注
message  OtherPlayerBetBroadcast
{
    BetArea curBet = 1; // 当前区域新增下注
    int32 uid = 2; // 暂时无用
}

// 牌桌信息请求。
// 玩家进入桌子、断线重连时主动拉取。
message TableInfoReq {
}

message TableInfoRes {
    uint32 state = 1;               // 桌子状态：0 结算/等待中，1 下注中
    uint32 timeLeft = 2;            // 当前状态剩余秒数
    uint32 curTurn = 3;             // 当前局号
    repeated uint64 availableChips = 4;      // 可下注筹码列表
    repeated BoxConfig boxList = 5;          // 8 个宝箱区域基础配置    "boxList": [{ "icon": 1, "name": "box_1", "ratio": 2 }],
    repeated uint32 bingoIcon = 6;           // 最近开奖记录，最旧在前、最新在后
    repeated BetArea betTotal = 7;           // 当前局玩家个人下注汇总   "betTotal": [{ "icon": 2, "money": 1000 }],
    uint64 totalGain = 9;           // 上一局或当前结算局玩家总返奖
    uint64 todayWin = 10;           // 玩家今日累计赢得金币
    repeated RankInfo betRank = 11;          // 最近一局赢家前三
    uint64 userMoney = 12;          // 玩家当前余额
    uint64 lastChips = 13;          // 玩家最近一次使用的筹码档位
    uint64 betStatTims = 14;        // 下注阶段总时长，单位秒
    RankInfo firstRank = 15;        // 排名第一的玩家信息
    repeated BetArea allAreaBetData = 16;    // 每个区域总下注金额      
    uint64 totalBet = 17;                     // 玩家本局总下注
    uint32 curBingoIcon = 18;                 // 本局主开奖结果图标，普通局为 1~8，大奖9
}

// 开始下注广播。
// 每轮进入下注阶段时广播一次。
message StartBetBroadcast {
    uint32 state = 1;   // 当前状态，固定为 1 表示下注中
    uint32 betTime = 2; // 本轮下注总时长，单位秒
    uint32 curTurn = 3; // 当前局号
}
 
message ResultBroadcast {
    uint32 state = 1;               // 当前状态，固定为 0 表示进入结算/等待
    uint32 settleTime = 2;          // 本次结算展示时长，单位秒
    uint32 curTurn = 3;             // 当前结算局号
    uint64 totalBet = 4;            // 玩家本局总下注
    uint64 totalGain = 5;           // 玩家本局总返奖
    uint64 userMoney = 6;           // 结算后的玩家最新余额
    uint64 todayWin = 7;            // 玩家今日累计赢得金币
    uint32 curBingoIcon = 8;        // 本局主开奖结果图标，普通局为 1~8，大奖9
    repeated uint32 resultIcons = 9;         // 实际中奖图标列表，普通局 1 个，大奖局 4 个
    repeated ResultArea resultAreas = 10;    // 玩家实际命中区域及返奖明细 [{ "icon": 3, "ratio": 4, "winMoney": 4000 }],
    repeated RankInfo betRank = 11;          // 本局赢钱前三玩家信息
    RankInfo firstRank = 12;        // 排名第一的玩家信息
}

// 玩家基础信息请求。
message GetUserDataReq {
}

// 玩家基础信息响应。
message GetUserDataRes {
    uint32 code = 1;       // 返回码，0 成功
    string desc = 2;       // 返回描述
    string name = 3;       // 玩家昵称
    string head = 4;       // 玩家头像URL
    uint64 userMoney = 5;  // 玩家当前余额
}

// 当日排行榜请求。
message GetRankDataReq {
}

// 当日排行榜响应。
// rankList 为排行榜数组，按 rank 升序返回前10名。
message GetRankDataRes {
    uint32 code = 1;          // 返回码，0 成功
    string desc = 2;          // 返回描述
    repeated RankInfo rankList = 3;    // 排行榜列表
}

// 玩家记录请求。
message GetUserRecordReq {
}

// 玩家记录响应。
// recordData 为数组，每个元素都是一个 RoundRecord。
message GetUserRecordRes {
    uint32 code = 1;             // 返回码，0 成功
    string desc = 2;             // 返回描述
    repeated RoundRecord recordData = 3;  // 玩家历史记录列表 最多只展示最新的25条
}

// 长时间未操作提示广播。
// tips_type:
// 0 表示进入空闲倒计时提醒
// 1 表示服务端要求客户端断线重连
message timeOutBroadcast {
    int32 tips_type = 1; // 提示类型：0 倒计时提醒，1 重新进入游戏
    string context = 2;  // 提示文案内容
}

//超时未操作提示状态刷新
message refreshStatReq
{

}

message refreshStatRes
{
  required int32 code = 1; // 0成功  1失败
  required string desc = 2; // code对应的描述
}
